434	## web — Invoker component + REST controller bridge
435	
436	The Invoker extends `InvokerWrapper`; its `@InvocationHandler` methods are the only place
437	gateways originate commands/queries. `getCommandGateway()` / `getQueryGateway()` are live
438	only inside these methods on the proxy returned by `EventoBundle.getInvoker(...)`.
439	
440	```java
441	package com.study.app.web;
442	
443	import com.evento.application.proxy.InvokerWrapper;
444	import com.evento.common.modeling.annotations.component.Invoker;
445	import com.evento.common.modeling.annotations.handler.InvocationHandler;
446	import com.study.app.domain.command.CreateOrderCommand;
447	import com.study.app.domain.query.FindOrderByIdQuery;
448	import com.study.app.domain.query.ListOrdersQuery;
449	import com.study.app.domain.view.OrderView;
450	
451	import java.util.Collection;
452	
453	@Invoker
454	public class OrderInvoker extends InvokerWrapper {
455	
456	    @InvocationHandler
457	    public String createOrder(String orderId, String description, int quantity) throws Exception {
458	        getCommandGateway().send(new CreateOrderCommand(orderId, description, quantity)).get();
459	        return orderId;
460	    }
461	
462	    @InvocationHandler
463	    public OrderView findOrder(String orderId) throws Exception {
464	        // query(...) resolves to Single<OrderView>; .getData() unwraps the view
465	        return getQueryGateway()
466	                .<com.evento.common.modeling.messaging.query.Single<OrderView>>query(new FindOrderByIdQuery(orderId))
467	                .get()
468	                .getData();
469	    }
470	
471	    @InvocationHandler
472	    public Collection<OrderView> listOrders() throws Exception {
473	        return getQueryGateway()
474	                .<com.evento.common.modeling.messaging.query.Multiple<OrderView>>query(new ListOrdersQuery())
475	                .get()
476	                .getData();
477	    }
478	}
